head.script:
	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

	//지도검색 팝업
scwin.btnMapInfo_onclick = function() {
	const flag = pgjUtil.getCookie('mapGuide');
    if (flag === 'Y') {
        pgjUtil.openMap();
    } else {

		/********* Popup Settings *********/
		var winW = window.innerWidth;
		var winH = window.innerHeight;

		/* default popup size */
		var popupW = 700;
		var popupH = 450;

		var popupX = (winW/2) - (popupW/2);
		var popupY = (winH/2) - (popupH/2);

		var options = {
			id: "popupMapGuide",
			type: "wframePopup",
			modal: true,
			popupName: "지도_안내문",
			top:popupY,
			left:popupX,
			width:popupW,
			height:popupH,
		};

		com.win.openPopup("/pgj/ui/pgj100/PGJ152P01.xml", options);
	}
};

/**
 * 페이지 이동 이벤트
 *
 * @param : [pgjId]
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.22.   나해준        [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pgjMoveSercPage = function (pgjId = 'PGJ151F00') {
	$p.url(`/pgj/ui/pgj100/${pgjId}.xml`,{ "spa" : false,
				  "replaceHistory" : true,
				  "param":{}
				});
}

/**
 * 
 * 다수조회 ,다수관심 메뉴 클릭 시 이동
 *
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ------------- ------------ --------------------------
 *  2024.06.28    나해준        [NELS] 최초생성
 * ============= ============ ==========================
 */
scwin.mjrtyItrtMenuMove = function(pgmDvsNum) {
    $p.url("/pgj/ui/pgj100/PGJ155M00.xml",{"spa" : false, "replaceHistory" : true,"param":{pgmDvsNum}})
}

/**
 * 메뉴 포커스
 *
 * @param : [pgjId]
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2025.01.07.   나해준        [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.menuFocus = function (pgjId) {
    $p.getComponentById(pgjId).addClass("on"); 
}
